<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {ArrowRight,Play,RotateCcw} from 'lucide-vue-next'
import Panel from '../components/Panel.vue'
import TelemetryChart from '../components/TelemetryChart.vue'
import {useWorkspace} from '../stores/workspace'
import {metricInfo,statusText} from '../domain'
import type {Metric} from '../domain'
import {causesFor} from '../services/demo'
const store=useWorkspace(),router=useRouter(),range=ref(24),metric=ref<Metric|'all'>('all'),eventIndex=ref(0),focus=ref(''),nodeIndex=ref(2),chart=ref<InstanceType<typeof TelemetryChart>>()
const c=computed(()=>store.context),d=computed(()=>store.state.detections.find(d=>d.context.segment.id===c.value?.segment.id&&d.status==='success')),a=computed(()=>store.state.analyses.find(a=>a.detectionId===d.value?.id)),event=computed(()=>d.value?.anomalies[eventIndex.value]??d.value?.anomalies[0])
const visibleCauses=computed(()=>d.value&&a.value?.status==='success'?causesFor(d.value,a.value.anomalyIds):[])
watch(()=>c.value?.segment.id,()=>{focus.value='';eventIndex.value=0;metric.value='all'})
function selectEvent(i:number){eventIndex.value=i;focus.value=d.value?.anomalies[i]?.id??''}
const nodes=[{name:'世纪花园西',sup:65.4,ret:41,p:.53,q:98},{name:'世纪花园东',sup:62.8,ret:40,p:.51,q:92},{name:'红旗三期G',sup:61.2,ret:38.4,p:.48,q:86.4},{name:'恒盛嘉庭',sup:64.1,ret:42,p:.54,q:112},{name:'龙兴家园',sup:65,ret:41.5,p:.52,q:100},{name:'经贸大厦',sup:66.2,ret:43,p:.53,q:88}]
const node=computed(()=>nodes[nodeIndex.value]!),cards:Metric[]=['supply','pressure','flow']
function network(kind:string){const s=store.state.segments.find(s=>s.networkId===c.value?.network.id&&s.kind===kind&&s.hasData);if(s)store.select(s.id);else store.notify('当前管网暂无该类型管段。')}
function detect(){router.push('/detections?create=1')}
function report(){if(!d.value){detect();return}router.push('/reports/'+store.createReport(d.value.id,a.value?.status==='success'?a.value.id:undefined))}
function value(m:Metric){return m==='supply'?(c.value?.segment.kind==='primary'?109.8:68.4):m==='pressure'?(c.value?.segment.kind==='primary'?1.62:.5):(c.value?.segment.kind==='primary'?1520:186.5)}
</script>
<template><div class="page-stack" v-if="c">
<div class="page-actions"><span class="muted">当前管段运行概览 · 数据快照 2026-11-03</span><button class="primary" @click="detect"><Play :size="16" />执行时序快速检测</button></div>
<div class="grid overview-top"><Panel title="管网热力工况核心测点监测"><template #tools><div class="segmented"><button :class="{selected:c.segment.kind==='primary'}" @click="network('primary')">一次网（主干高温）</button><button :class="{selected:c.segment.kind==='secondary'}" @click="network('secondary')">二次网（换热分支）</button></div></template><div v-if="c.segment.hasData" class="grid metrics-three"><button v-for="m in cards.filter(m=>c!.segment.metrics.includes(m))" :key="m" :class="['metric-card',{chosen:metric===m}]" @click="metric=metric===m?'all':m"><div class="flex between"><strong>{{metricInfo[m].label}}</strong><span :class="['badge',m==='flow'?'amber':'green']">{{m==='flow'?'-4.2':'+0.02'}} {{metricInfo[m].unit}}</span></div><div class="metric-value">{{value(m)}}<small>{{metricInfo[m].unit}}</small></div><p class="muted">示例参考区间 · 非检测配置</p><svg class="spark" viewBox="0 0 240 36" preserveAspectRatio="none" aria-hidden="true"><path d="M0 24 Q40 8 80 20 T160 22 T240 15" fill="none" :stroke="metricInfo[m].color" stroke-width="2" /></svg></button></div><div v-else class="empty">当前管段暂无运行数据。<RouterLink to="/networks">切换管段</RouterLink></div><div class="inset summary-line">主选遥测通道：<strong class="orange">{{metric==='all'?'全部可用参数':metricInfo[metric].label}}</strong><span>数据完整率：<b class="green">99.85%（演示）</b></span><span>工况示例：<b class="orange">异常关注</b></span></div></Panel>
<Panel title="待分析异常摘要" tone="danger-panel"><template #tools><span class="muted">当前检测</span></template><div class="flex between"><strong class="big-number red">{{d?.anomalies.length??0}}</strong><div class="stack-small"><span class="badge red">显著偏差：{{d?.anomalies.filter(x=>x.level==='显著偏差').length??0}} 项</span><span class="badge amber">轻度波动：{{d?.anomalies.filter(x=>x.level==='轻度波动').length??0}} 项</span></div></div><p class="muted">待人工核查的示例异常，不代表实际运行告警</p><button v-for="(e,i) in d?.anomalies" :key="e.id" class="event-compact" @click="selectEvent(i)"><span class="mono muted">{{new Date(e.start).toLocaleTimeString('zh-CN',{hour12:false})}}</span><strong>{{e.title}}</strong><span class="badge red">待分析</span></button><button class="wide secondary red" @click="router.push(d?'/detections/'+d.id:'/detections')">进入异常检测工作台 <ArrowRight :size="16" /></button></Panel></div>
<Panel title="高精时序遥测趋势与异常区间"><template #tools><div class="segmented"><button v-for="r in [1,6,12,24]" :key="r" :class="{selected:range===r}" @click="range=r">{{r}}h</button></div><button class="icon-button" aria-label="复位趋势视窗" @click="chart?.reset()"><RotateCcw :size="16" /></button></template><TelemetryChart :key="c.segment.id+'-'+range" ref="chart" :context="c" :metrics="metric==='all'?c.segment.metrics:[metric]" start="2026-11-03T00:00" :end="'2026-11-03T'+String(range===24?23:range).padStart(2,'0')+':'+(range===24?'59':'00')" :anomalies="d?.anomalies" :focus-id="focus" @select="id=>{selectEvent(d?.anomalies.findIndex(a=>a.id===id)??0)}" /><p class="chart-caption">橙色：供水温度　青色：回水温度　紫色：压力　蓝色：流量 · 各单位独立坐标，滚轮可缩放</p></Panel>
<div class="grid two-one"><Panel title="供热管网水力拓扑与末端热力平衡图"><template #tools><span class="orange">供水管网</span><span class="cyan">回水管网</span></template><div class="topology"><svg viewBox="0 0 800 260" role="img" aria-label="供热管网结构，点击末端节点查看详情"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#242b35" /></pattern></defs><rect width="800" height="260" fill="url(#dots)" /><path d="M66 120H190V60H740M190 60V195H740" fill="none" stroke="#ff7849" stroke-width="3" /><path d="M66 138H178V78H740M178 78V213H740" fill="none" stroke="#00b4d8" stroke-width="3" /><circle cx="45" cy="130" r="28" fill="#14161b" stroke="#fb7a18" stroke-width="2"/><text x="45" y="134" fill="#fb7a18" text-anchor="middle" font-size="11">热源厂</text><rect x="100" y="102" width="62" height="54" fill="#101116" stroke="#00b4d8"/><text x="130" y="128" text-anchor="middle" fill="#e8e9ed" font-size="11">换热站</text><text x="130" y="146" text-anchor="middle" fill="#00b4d8" font-size="9">#01 中继</text></svg><div class="topology-nodes"><button v-for="(n,i) in nodes" :key="n.name" :class="['topology-node',{selected:i===nodeIndex,warn:i===2}]" @click="nodeIndex=i"><strong><i :class="['dot',{bad:i===2}]"></i>{{n.name}}</strong><span class="orange mono">{{n.sup}} ℃</span><small>{{n.p}}MPa · {{n.q}}m³/h</small></button></div></div></Panel>
<Panel title="选中末端测点遥测工况"><template #tools><span :class="['badge',nodeIndex===2?'red':'green']">{{nodeIndex===2?'异常关注':'工况稳定'}}</span></template><p class="muted">{{node.name}} · 建筑二级分区</p><div class="metric-value orange">{{node.sup}}<small>℃ 供水测点</small></div><dl class="detail-list"><div><dt>末端回水温度</dt><dd>{{node.ret}} ℃</dd></div><div><dt>供回温差</dt><dd class="orange">{{(node.sup-node.ret).toFixed(1)}} ℃</dd></div><div><dt>进端管网压力</dt><dd>{{node.p}} MPa</dd></div><div><dt>瞬时循环流量</dt><dd>{{node.q}} m³/h</dd></div></dl><div class="inset muted">核查提示：结合末端测温和现场阀门状态进行人工核验。本图为可交互的示例拓扑。</div></Panel></div>
<div class="grid bottom-three"><Panel title="时序异常明细"><template #tools><span class="muted">点击行联动分析</span></template><div class="table-wrap"><table><thead><tr><th>时间</th><th>异常现象</th><th>参数变化</th></tr></thead><tbody><tr v-for="(e,i) in d?.anomalies" :key="e.id" :class="{selected:i===eventIndex}" tabindex="0" @click="selectEvent(i)" @keydown.enter="selectEvent(i)"><td class="mono">{{e.start.slice(11,19)}}</td><td>{{e.title}}</td><td class="orange">{{e.baseline}} → {{e.value}} {{metricInfo[e.metric].unit}}</td></tr><tr v-if="!d?.anomalies.length"><td colspan="3" class="empty">暂无检测异常</td></tr></tbody></table></div></Panel>
<Panel title="自研小模型辅助诊断"><template #tools><span class="badge purple">示例结果</span></template><div class="flex"><div v-if="visibleCauses.length" class="score-ring">{{Math.round(visibleCauses[0]!.weight)}}<span>%</span></div><div><h3>{{event?.title??'暂无异常'}}</h3><p class="muted">{{event?.evidence??'请先完成异常检测'}}</p></div></div><div v-for="cause in visibleCauses" :key="cause.title" class="weight"><div class="flex between"><span>{{cause.title}}</span><b class="orange">{{cause.weight}}%</b></div><div class="bar"><span :style="{width:cause.weight+'%'}"></span></div></div><p class="muted small">{{visibleCauses.length?'示例权重与评分，不代表模型实际置信度':'暂无已完成的 AI 分析，请先选取异常发起分析。'}}</p></Panel>
<Panel title="AI 分析执行状态"><template #tools><span class="badge green">演示服务</span></template><ol class="stages"><li v-for="(s,i) in ['接收','切片','特征','分析','建议']" :key="s" :class="{done:a?.status==='success'||(a?.status==='running'&&i<2)}"><span>{{i+1}}</span>{{s}}</li></ol><dl class="detail-list"><div><dt>关联检测任务</dt><dd>{{d?.id??'未创建'}}</dd></div><div><dt>分析状态</dt><dd>{{a?statusText[a.status]:'未发起'}}</dd></div><div><dt>分析来源</dt><dd>当前管段检测结果</dd></div></dl><button class="wide secondary" @click="router.push(a?'/analysis/'+a.id:'/analysis')">查看完整 AI 辅助诊断 <ArrowRight :size="16" /></button><button class="wide primary mt" @click="report">生成诊断报告</button></Panel></div>
</div><div v-else class="empty">请先<RouterLink to="/networks">选择管段</RouterLink>。</div></template>
